import { ArrowRight, BriefcaseBusiness, MessageCircle, Save, Settings2 } from "lucide-react";
import { FormEvent, useMemo, useRef, useState } from "react";
import { repairText } from "../lib/copy";
import type { Position, WorkspaceState } from "../types";
import type { InterviewConfig } from "./shared";

type IntakeMessage = {
  id: string;
  role: "assistant" | "user";
  text: string;
};

type DraftSummary = {
  company: string;
  role: string;
  interviewer: string;
  difficulty: string;
  experience: string;
  duration: string;
  text: string;
};

function buildDraftJd(input: string): DraftSummary {
  const normalized = input.trim();
  const companyMatch = normalized.match(/(字节|腾讯|阿里|美团|快手|小红书|百度|网易|京东|滴滴|华为|米哈游|拼多多)/);
  const roleMatch = normalized.match(/(AI\s*)?(产品经理|产品运营|前端|后端|设计师|数据分析|商业分析|算法|测试|项目经理|增长)/i);
  const company = companyMatch?.[1] ?? "目标公司";
  const role = roleMatch?.[0]?.replace(/\s+/g, " ").trim() ?? "目标岗位";
  const interviewer = normalized.includes("CTO") ? "CTO" : normalized.includes("HR") ? "HR" : normalized.includes("业务") ? "业务负责人" : "上级";
  const difficulty = normalized.includes("压力") ? "压力面" : normalized.includes("地狱") ? "地狱面" : "正常";
  const experience = normalized.match(/(\d+\s*-\s*\d+年|\d+年\+?|应届|校招|实习)/)?.[0] ?? "1-3年";
  const duration = normalized.match(/(\d+\s*(分钟|min))/i)?.[0]?.replace(/\s+/g, "") ?? "30分钟";

  return {
    company,
    role,
    interviewer,
    difficulty,
    experience,
    duration,
    text: [
      `公司：${company}`,
      `岗位：${role}`,
      `面试官：${interviewer}`,
      `难度：${difficulty}`,
      `时长：${duration}`,
      `经验要求：${experience}`,
      "岗位职责：围绕业务目标拆解问题，结合用户、数据和项目推进经验完成方案设计与落地。",
      "任职要求：具备结构化表达、项目复盘、跨团队协作和可量化结果意识，能结合真实项目回答追问。",
    ].join("\n"),
  };
}

function buildFollowUp(input: string, draft: DraftSummary) {
  const normalized = input.trim();
  const missing: string[] = [];

  if (!/(字节|腾讯|阿里|美团|快手|小红书|百度|网易|京东|滴滴|华为|米哈游|拼多多)/.test(normalized)) {
    missing.push("目标公司");
  }
  if (!/(产品经理|产品运营|前端|后端|设计师|数据分析|商业分析|算法|测试|项目经理|增长)/i.test(normalized)) {
    missing.push("岗位方向");
  }
  if (!/(HR|CTO|业务|上级)/.test(normalized)) {
    missing.push("面试官类型");
  }
  if (!/(压力|地狱|正常)/.test(normalized)) {
    missing.push("面试难度");
  }
  if (!/(\d+\s*(分钟|min))/i.test(normalized)) {
    missing.push("面试时长");
  }

  if (missing.length === 0) {
    return `收到。我已经先按“${draft.company} · ${draft.role} · ${draft.interviewer} · ${draft.difficulty} · ${draft.duration}”整理好岗位草稿。继续把 JD 原文、业务背景或你最担心的追问题型告诉我。`;
  }

  return `收到。我先帮你建了一个“${draft.company} · ${draft.role}”草稿。下一轮继续告诉我：${missing.join("、")}。`;
}

function fieldValue(position: Position | undefined, key: string, fallback = "") {
  return repairText(position?.intake?.fields.find((field) => field.key === key)?.value ?? fallback);
}

