  const visibleMessages = expandedThread ? messages : messages.slice(-3);

  const submit = (event: FormEvent) => {
    event.preventDefault();
    const text = input.trim();
    if (!text) return;

    const nextContext = [intakeContext, text].filter(Boolean).join("\n");
    const draft = buildDraftJd(nextContext);
    setIntakeContext(nextContext);
    setGeneratedJd(draft.text);
    setMessages((current) => [
      ...current,
      { id: `home-user-${current.length + 1}`, role: "user", text },
      {
        id: `home-assistant-${current.length + 2}`,
