            <div className="home-thread home-thread-wide">
              {messages.length > 3 && !expandedThread ? (
                <button className="thread-expand-button" type="button" onClick={() => setExpandedThread(true)}>
                  查看完整对话
                </button>
              ) : null}
              {visibleMessages.map((message) => (
                <article key={message.id} className={message.role === "assistant" ? "chat-bubble assistant" : "chat-bubble user"}>
                  <p>{message.text}</p>
