              createdAt: timestamp,
            },
          ],
    fields: [
      { key: "goal", label: "目标", value: fieldValue("goal", job.title), confirmed: Boolean(fieldValue("goal", job.title)) },
      { key: "role", label: "岗位方向", value: fieldValue("role", job.title), confirmed: Boolean(fieldValue("role", job.title)) },
