      { key: "difficulty", label: "难度", value: fieldValue("difficulty", "正常难度"), confirmed: true },
      { key: "duration", label: "时长", value: fieldValue("duration", "30分钟"), confirmed: true },
      { key: "hasJd", label: "JD", value: fieldValue("hasJd", jobText.trim() ? "已生成" : "待补充"), confirmed: Boolean(jobText.trim()) },
    ],
    suggestedPrompts: previous?.suggestedPrompts?.length
      ? previous.suggestedPrompts
